//! High-accuracy, multi-WAN HTTP/1.1 upload bandwidth tester.
//! Key guarantees:
//! 1. Strict 3-way accounting: generated bytes, client-sent bytes, and server-confirmed bytes.
//!    Official upload throughput only counts server-confirmed HTTP POST completions.
//! 2. Dynamic HTTP POST payload sizing across 4 MiB, 8 MiB, 16 MiB, 32 MiB (and adaptive
//!    shrink on 413 / slow links).
//! 3. Automatic concurrency optimization across [1, 2, 4, 8, 16, 32, 64] tiers.
//! 4. Independent per-node and per-IP metrics with least-active atomic IP dispersion.
//! 5. Excludes raw TCP targets from valid upload speedtest (no application-level ACK).

use std::collections::HashMap;
use std::net::SocketAddr;
use std::pin::Pin;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::task::{Context, Poll};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use bytes::Bytes;
use futures_core::Stream;
use tokio::net::{TcpStream, lookup_host};
use tokio::sync::Notify;
use tokio::task::JoinSet;

use crate::conn_tester::CancelToken;
use crate::downloader::extract_host_port;
use crate::state::{
    CONCURRENCY_TIERS, DEFAULT_HTTP_POST_BYTES, IpEndpointMetrics, MemoryLog, NodeSpeedMetrics,
    SharedStats, TestConfig, compute_median, compute_p95, format_bytes, format_mbps,
};

const UPLOAD_BUF_SIZE: usize = 1024 * 1024; // 1 MiB reusable RAM buffer
const UPLOAD_SLICE_SIZE: usize = 256 * 1024; // 256 KiB slice yield
const PROBE_POST_BYTES: usize = 512 * 1024; // 512 KiB pre-flight probe
const STALL_TIMEOUT_MS: u64 = 8000;
const POST_SIZE_TIERS: [usize; 4] = [
    4 * 1024 * 1024,
    8 * 1024 * 1024,
    16 * 1024 * 1024,
    32 * 1024 * 1024,
];

#[derive(Clone)]
struct UploadNode {
    url: String,
    host: String,
    edge_addrs: Vec<SocketAddr>,
    metrics: Arc<NodeSpeedMetrics>,
}

pub fn parse_http_upload_targets(raw_targets: &[String]) -> (Vec<String>, Vec<String>) {
    let mut http_urls = Vec::new();
    let mut rejected = Vec::new();
    for s in raw_targets {
        let trimmed = s.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with("http://") || trimmed.starts_with("https://") {
            if !http_urls.contains(&trimmed.to_owned()) {
                http_urls.push(trimmed.to_owned());
            }
        } else {
            rejected.push(trimmed.to_owned());
        }
    }
    (http_urls, rejected)
}

/// Generate an incompressible buffer in RAM using xorshift64*.
pub fn make_in_memory_random_bytes(size: usize) -> Bytes {
    let seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0x9E37_79B9_7F4A_7C15)
        ^ 0xA076_1D64_78BD_642F;
    let mut state = if seed == 0 {
        0x1234_5678_9ABC_DEF0
    } else {
        seed
    };
    let mut buf = vec![0u8; size];
    for chunk in buf.chunks_mut(8) {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        let bytes = state.to_le_bytes();
        let n = chunk.len();
        chunk.copy_from_slice(&bytes[..n]);
    }
    Bytes::from(buf)
}

async fn resolve_edge_ips(host: &str, port: u16) -> Vec<SocketAddr> {
    let mut v4 = Vec::new();
    let mut v6 = Vec::new();
    if let Ok(Ok(addrs)) =
        tokio::time::timeout(Duration::from_secs(3), lookup_host((host, port))).await
    {
        for addr in addrs {
            if addr.is_ipv4() {
                if v4.len() < 8 && !v4.contains(&addr) {
                    v4.push(addr);
                }
            } else if v6.len() < 4 && !v6.contains(&addr) {
                v6.push(addr);
            }
        }
    }
    if v4.is_empty() { v6 } else { v4 }
}

fn build_http1_client(
    pinned: Option<(&str, SocketAddr)>,
    connect_secs: u64,
) -> Option<reqwest::Client> {
    let mut builder = reqwest::Client::builder()
        .http1_only()
        .connect_timeout(Duration::from_secs(connect_secs))
        .tcp_nodelay(true)
        .tcp_keepalive(Duration::from_secs(15))
        .pool_max_idle_per_host(2)
        .user_agent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) WinNetStress/0.4");

    if let Some((host, addr)) = pinned {
        builder = builder.resolve(host, addr);
    }

    builder.build().ok()
}

struct InMemoryUploadStream {
    chunk: Bytes,
    offset: usize,
    remaining: usize,
    stats: Option<Arc<SharedStats>>,
    node_metrics: Option<Arc<NodeSpeedMetrics>>,
    pushed_bytes: Arc<AtomicUsize>,
    last_progress_ms: Arc<AtomicU64>,
    start_instant: tokio::time::Instant,
    cancel: Arc<CancelToken>,
}

impl Stream for InMemoryUploadStream {
    type Item = Result<Bytes, std::io::Error>;

    fn poll_next(mut self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        if self.cancel.is_cancelled() || self.remaining == 0 {
            return Poll::Ready(None);
        }
        let avail_in_buf = self.chunk.len() - self.offset;
        let to_send = self.remaining.min(UPLOAD_SLICE_SIZE).min(avail_in_buf);
        let slice = self.chunk.slice(self.offset..(self.offset + to_send));
        self.offset = (self.offset + to_send) % self.chunk.len();
        self.remaining -= to_send;

        // Track generated bytes and client-sent bytes separately from server-confirmed bytes.
        if let Some(stats) = &self.stats {
            stats
                .up_bytes_body_yielded
                .fetch_add(to_send as u64, Ordering::Relaxed);
        }
        if let Some(nm) = &self.node_metrics {
            nm.bytes_client
                .fetch_add(to_send as u64, Ordering::Relaxed);
        }
        self.pushed_bytes.fetch_add(to_send, Ordering::Relaxed);
        self.last_progress_ms.store(
            self.start_instant.elapsed().as_millis() as u64,
            Ordering::Relaxed,
        );

        Poll::Ready(Some(Ok(slice)))
    }
}

async fn probe_and_rank_upload_targets(
    urls: Vec<String>,
    payload: Bytes,
    cancel: &Arc<CancelToken>,
    log: &MemoryLog,
) -> Vec<UploadNode> {
    let mut set = JoinSet::new();

    for url in urls {
        let payload = payload.clone();
        let cancel = cancel.clone();

        set.spawn(async move {
            let Some((host, port)) = extract_host_port(&url) else {
                return None;
            };
            let edge_addrs = resolve_edge_ips(&host, port).await;
            if edge_addrs.is_empty() {
                return None;
            }

            let t_tcp = Instant::now();
            let tcp_ok = tokio::time::timeout(
                Duration::from_millis(1800),
                TcpStream::connect(edge_addrs[0]),
            )
            .await;
            let tcp_ms = match tcp_ok {
                Ok(Ok(s)) => {
                    drop(s);
                    t_tcp.elapsed().as_millis().max(1) as u64
                }
                _ => return None,
            };

            let pinned = Some((host.as_str(), edge_addrs[0]));
            let client = build_http1_client(pinned, 3)?;

            // Run up to 2 probes to estimate median upload speed and verify HTTP POST acceptance
            let mut probe_len = PROBE_POST_BYTES;
            let mut probe_samples = Vec::new();
            let mut initial_post_bytes = DEFAULT_HTTP_POST_BYTES;

            for round in 0..2 {
                if cancel.is_cancelled() {
                    return None;
                }
                let pushed = Arc::new(AtomicUsize::new(0));
                let lp = Arc::new(AtomicU64::new(0));
                let stream = InMemoryUploadStream {
                    chunk: payload.clone(),
                    offset: 0,
                    remaining: probe_len,
                    stats: None,
                    node_metrics: None,
                    pushed_bytes: pushed.clone(),
                    last_progress_ms: lp,
                    start_instant: tokio::time::Instant::now(),
                    cancel: cancel.clone(),
                };

                let t0 = Instant::now();
                let req = client
                    .post(&url)
                    .header(reqwest::header::CONTENT_TYPE, "application/octet-stream")
                    .header(reqwest::header::CONTENT_LENGTH, probe_len as u64)
                    .body(reqwest::Body::wrap_stream(stream))
                    .send();

                match tokio::time::timeout(Duration::from_secs(4), req).await {
                    Ok(Ok(resp)) => {
                        let status = resp.status();
                        let sent = pushed.load(Ordering::Relaxed);
                        let elapsed_ns = t0.elapsed().as_nanos().max(1) as f64;
                        let bps = ((sent as f64) * 8.0 * 1_000_000_000.0 / elapsed_ns) as u64;

                        if is_complete_successful_upload(status, sent, probe_len) {
                            probe_samples.push(bps);
                            if round == 0 && t0.elapsed() < Duration::from_millis(250) {
                                initial_post_bytes = 8 * 1024 * 1024;
                            }
                        } else if status.as_u16() == 413 && probe_len > 128 * 1024 {
                            probe_len = 128 * 1024;
                            initial_post_bytes = 2 * 1024 * 1024;
                        } else {
                            // A partial request body or any 4xx/5xx response is not a valid upload sample.
                            return None;
                        }
                    }
                    _ => {
                        if probe_samples.is_empty() {
                            return None;
                        }
                    }
                }
            }

            if probe_samples.is_empty() {
                return None;
            }

            let median_bps = compute_median(&probe_samples);
            let metrics = Arc::new(NodeSpeedMetrics::new(
                host.clone(),
                url.clone(),
                median_bps,
                tcp_ms,
                0,
                0,
                false,
                &edge_addrs,
            ));
            metrics
                .current_post_bytes
                .store(initial_post_bytes, Ordering::Relaxed);

            Some(UploadNode {
                url,
                host,
                edge_addrs,
                metrics,
            })
        });
    }

    let mut chosen = Vec::new();

    while let Some(res) = tokio::select! {
        biased;
        _ = cancel.cancelled() => {
            set.abort_all();
            return Vec::new();
        }
        r = set.join_next() => r,
    } {
        if let Ok(Some(node)) = res {
            chosen.push(node);
        }
    }

    chosen.sort_by_key(|n| std::cmp::Reverse(n.metrics.probe_bps.load(Ordering::Relaxed)));
    if chosen.is_empty() {
        return chosen;
    }

    let best_bps = chosen[0].metrics.probe_bps.load(Ordering::Relaxed);
    let floor_bps = best_bps / 5;
    let mut selected: Vec<UploadNode> = chosen
        .iter()
        .enumerate()
        .filter(|(i, n)| *i < 3 || n.metrics.probe_bps.load(Ordering::Relaxed) >= floor_bps)
        .map(|(_, n)| n.clone())
        .collect();
    selected.truncate(6);

    let summary: Vec<String> = selected
        .iter()
        .map(|n| {
            format!(
                "{}({}·{}IP)",
                n.host,
                format_mbps(n.metrics.probe_bps.load(Ordering::Relaxed)),
                n.edge_addrs.len()
            )
        })
        .collect();
    log.push(format!(
        "上行预探测优选 {} 个节点: {}",
        selected.len(),
        summary.join(", ")
    ));

    selected
}

fn is_complete_successful_upload(status: reqwest::StatusCode, body_yielded: usize, expected: usize) -> bool {
    status.is_success() && body_yielded == expected
}

/// Step HTTP POST payload across [4 MiB, 8 MiB, 16 MiB, 32 MiB] based on request/response time.
pub fn adapt_post_size(current: usize, elapsed_ms: u64) -> usize {
    if elapsed_ms <= 650 {
        for &tier in &POST_SIZE_TIERS {
            if tier > current {
                return tier;
            }
        }
        POST_SIZE_TIERS[POST_SIZE_TIERS.len() - 1]
    } else if elapsed_ms >= 4500 && current > POST_SIZE_TIERS[0] {
        (current / 2).max(POST_SIZE_TIERS[0])
    } else {
        current
    }
}

fn select_weighted_upload_node(nodes: &[UploadNode], cycle: usize) -> usize {
    let mut total_w = 0u64;
    let mut active_indices = Vec::new();
    for (i, n) in nodes.iter().enumerate() {
        if !n.metrics.quarantined.load(Ordering::Relaxed) {
            let w = n.metrics.weight.load(Ordering::Relaxed).max(1) as u64;
            total_w += w;
            active_indices.push((i, w));
        }
    }
    if active_indices.is_empty() {
        for n in nodes {
            n.metrics.quarantined.store(false, Ordering::Relaxed);
            n.metrics.consecutive_fails.store(0, Ordering::Relaxed);
        }
        return cycle % nodes.len();
    }
    let pick = ((cycle as u64).wrapping_mul(2_654_435_761) >> 16) % total_w;
    let mut acc = 0u64;
    for (idx, w) in active_indices {
        acc += w;
        if pick < acc {
            return idx;
        }
    }
    0
}

fn refresh_upload_weights(nodes: &[UploadNode]) {
    let best_ema = nodes
        .iter()
        .filter(|n| !n.metrics.quarantined.load(Ordering::Relaxed))
        .map(|n| n.metrics.ema_bps.load(Ordering::Relaxed))
        .max()
        .unwrap_or(1)
        .max(1);

    for n in nodes {
        let ema = n.metrics.ema_bps.load(Ordering::Relaxed);
        let pct = n.metrics.success_rate_pct();
        let rel = ((ema * 80) / best_ema).clamp(2, 80);
        let w = ((rel as f64) * (pct / 100.0)).round().clamp(1.0, 100.0) as u32;
        n.metrics.weight.store(w, Ordering::Relaxed);
    }
}

pub async fn run_upload_test(
    config: TestConfig,
    stats: Arc<SharedStats>,
    log: Arc<MemoryLog>,
    cancel: Arc<CancelToken>,
) {
    let (http_urls, rejected) = parse_http_upload_targets(&config.upload_targets);
    if !rejected.is_empty() {
        log.push(format!(
            "提示：已忽略非 HTTP 目标（Raw TCP 无服务端确认机制，不能作为有效上传测速）: {}",
            rejected.join(", ")
        ));
    }
    if http_urls.is_empty() {
        log.push("错误：没有有效的 HTTP/HTTPS 上传目标。");
        return;
    }

    log.push("正在内存中生成 1 MiB 不可压缩测试载荷（仅内存，零磁盘读写）...");
    let payload = make_in_memory_random_bytes(UPLOAD_BUF_SIZE);

    log.push(format!(
        "正在对 {} 个上行节点执行多轮中位数预探测与 IP 发现...",
        http_urls.len()
    ));

    let nodes = probe_and_rank_upload_targets(http_urls, payload.clone(), &cancel, &log).await;
    if cancel.is_cancelled() {
        return;
    }
    if nodes.is_empty() {
        log.push("错误：所有上行候选节点预探测均不可用，请检查网络或自定义上传目标。");
        return;
    }

    *stats.up_node_metrics.lock() = nodes.iter().map(|n| n.metrics.clone()).collect();

    let max_workers = 64usize;
    let initial_conc = if config.auto_concurrency {
        CONCURRENCY_TIERS[0] // start adaptive search from 1 -> 2 -> 4 -> 8 -> 16 -> 32 -> 64
    } else {
        config.up_concurrency.clamp(1, 64)
    };

    let target_conc = Arc::new(AtomicUsize::new(initial_conc));
    let conc_notify = Arc::new(Notify::new());
    stats
        .up_current_concurrency
        .store(initial_conc, Ordering::Relaxed);
    stats
        .up_best_concurrency
        .store(initial_conc, Ordering::Relaxed);

    let dur_desc = if config.duration_secs == 0 {
        "持续运行（手动停止）".to_string()
    } else {
        format!("{} 秒（前 {} 秒预热）", config.duration_secs, config.warmup_secs)
    };
    log.push(format!(
        "开始上行带宽压测：自动并发寻优={}，初始并发={initial_conc}，时长={dur_desc}",
        if config.auto_concurrency { "开启(1~64)" } else { "关闭" }
    ));

    let nodes = Arc::new(nodes);
    let last_err_log_ms = Arc::new(AtomicU64::new(0));
    let start_instant = tokio::time::Instant::now();
    let test_cancel = Arc::new(CancelToken::new());

    // Coordinator task: duration timer, adaptive concurrency search, weight refresh, valid-window stats
    let coord_cancel = cancel.clone();
    let coord_test_cancel = test_cancel.clone();
    let coord_stats = stats.clone();
    let coord_nodes = nodes.clone();
    let coord_target_conc = target_conc.clone();
    let coord_notify = conc_notify.clone();
    let coord_log = log.clone();
    let auto_conc = config.auto_concurrency;
    let duration_secs = config.duration_secs;
    let warmup_secs = config.warmup_secs;

    let coord_task = tokio::spawn(async move {
        let mut tier_idx = 0usize;
        let mut tier_started_at = Instant::now();
        let mut tier_start_confirmed = 0u64;
        let mut tier_start_ok = 0u64;
        let mut tier_start_fail = 0u64;
        let mut best_tier = initial_conc;
        let mut best_tier_bps = 0u64;
        let mut search_done = !auto_conc;

        let mut warmup_captured = warmup_secs == 0;
        let mut valid_start_bytes = 0u64;
        let mut valid_start_time = Instant::now();
        let mut valid_samples: Vec<u64> = Vec::new();
        let mut last_sample_bytes = 0u64;
        let mut last_sample_time = Instant::now();

        let mut tick = tokio::time::interval(Duration::from_millis(500));
        loop {
            tokio::select! {
                biased;
                _ = coord_cancel.cancelled() => {
                    coord_test_cancel.cancel();
                    break;
                }
                _ = tick.tick() => {}
            }

            let elapsed_s = start_instant.elapsed().as_secs();
            if duration_secs > 0 && elapsed_s >= duration_secs {
                coord_log.push(format!("上行测速达到设定时长 {duration_secs} 秒，正在汇总报告..."));
                coord_test_cancel.cancel();
                break;
            }

            let now_confirmed = coord_stats.up_bytes_total.load(Ordering::Relaxed);
            let now_time = Instant::now();

            // Capture post-warmup valid window baseline
            if !warmup_captured && elapsed_s >= warmup_secs {
                warmup_captured = true;
                valid_start_bytes = now_confirmed;
                valid_start_time = now_time;
            }

            // Record 500ms valid-window throughput sample & average
            let dt = now_time.duration_since(last_sample_time).as_secs_f64();
            if dt > 0.05 {
                let delta_b = now_confirmed.saturating_sub(last_sample_bytes);
                let inst_bps = ((delta_b as f64) * 8.0 / dt) as u64;
                last_sample_bytes = now_confirmed;
                last_sample_time = now_time;
                if warmup_captured {
                    valid_samples.push(inst_bps);
                    let valid_dt = now_time.duration_since(valid_start_time).as_secs_f64();
                    if valid_dt > 0.2 {
                        let valid_bytes = now_confirmed.saturating_sub(valid_start_bytes);
                        let avg_bps = ((valid_bytes as f64) * 8.0 / valid_dt) as u64;
                        coord_stats.up_bps_avg.store(avg_bps, Ordering::Relaxed);
                    }
                    coord_stats
                        .up_bps_p95
                        .store(compute_p95(&valid_samples), Ordering::Relaxed);
                }
            }

            refresh_upload_weights(&coord_nodes);

            // Auto concurrency search across [1, 2, 4, 8, 16, 32, 64]
            if !search_done {
                let tier_dur = tier_started_at.elapsed().as_secs_f64();
                if tier_dur >= 2.5 {
                    let cur_tier = CONCURRENCY_TIERS[tier_idx];
                    let tier_bytes = now_confirmed.saturating_sub(tier_start_confirmed);
                    let tier_bps = ((tier_bytes as f64) * 8.0 / tier_dur) as u64;

                    let ok_now = coord_stats.up_requests_ok.load(Ordering::Relaxed);
                    let fail_now = coord_stats.up_requests_fail.load(Ordering::Relaxed);
                    let d_ok = ok_now.saturating_sub(tier_start_ok);
                    let d_fail = fail_now.saturating_sub(tier_start_fail);
                    let fail_pct = if d_ok + d_fail > 0 {
                        (d_fail as f64) * 100.0 / ((d_ok + d_fail) as f64)
                    } else {
                        0.0
                    };

                    let improved = tier_bps > (best_tier_bps * 105) / 100 || best_tier_bps == 0;
                    if fail_pct <= 18.0 && (improved || tier_bps >= best_tier_bps) {
                        best_tier = cur_tier;
                        best_tier_bps = tier_bps;
                        coord_stats
                            .up_best_concurrency
                            .store(best_tier, Ordering::Relaxed);
                    }

                    let should_stop_climbing = fail_pct > 20.0
                        || (tier_idx >= 2 && !improved)
                        || tier_idx + 1 >= CONCURRENCY_TIERS.len();

                    if should_stop_climbing {
                        search_done = true;
                        coord_target_conc.store(best_tier, Ordering::Release);
                        coord_stats
                            .up_current_concurrency
                            .store(best_tier, Ordering::Relaxed);
                        coord_stats
                            .up_best_concurrency
                            .store(best_tier, Ordering::Relaxed);
                        coord_notify.notify_waiters();
                        coord_log.push(format!(
                            "上行自动寻优完成：最佳稳定并发={best_tier} (测得有效速率 {}, 失败率 {fail_pct:.1}%)",
                            format_mbps(best_tier_bps)
                        ));
                    } else {
                        tier_idx += 1;
                        let next_tier = CONCURRENCY_TIERS[tier_idx];
                        coord_target_conc.store(next_tier, Ordering::Release);
                        coord_stats
                            .up_current_concurrency
                            .store(next_tier, Ordering::Relaxed);
                        coord_notify.notify_waiters();
                        tier_started_at = Instant::now();
                        tier_start_confirmed = now_confirmed;
                        tier_start_ok = ok_now;
                        tier_start_fail = fail_now;
                        coord_log.push(format!(
                            "上行并发寻优：档位 {cur_tier}={} -> 尝试提升至 {next_tier}",
                            format_mbps(tier_bps)
                        ));
                    }
                }
            }
        }
    });

    let mut workers = JoinSet::new();
    for worker_id in 0..max_workers {
        let nodes = nodes.clone();
        let payload = payload.clone();
        let stats = stats.clone();
        let log = log.clone();
        let cancel = test_cancel.clone();
        let target_conc = target_conc.clone();
        let conc_notify = conc_notify.clone();
        let last_err_log_ms = last_err_log_ms.clone();

        workers.spawn(async move {
            let mut client_cache: HashMap<(usize, SocketAddr), reqwest::Client> = HashMap::new();
            let mut cycle = worker_id;

            while !cancel.is_cancelled() {
                while worker_id >= target_conc.load(Ordering::Acquire) {
                    if cancel.is_cancelled() {
                        return;
                    }
                    tokio::select! {
                        biased;
                        _ = cancel.cancelled() => return,
                        _ = conc_notify.notified() => {}
                    }
                }

                cycle = cycle.wrapping_add(1);
                let node_idx = select_weighted_upload_node(&nodes, cycle);
                let node = &nodes[node_idx];

                let chosen_ip: Option<Arc<IpEndpointMetrics>> = node.metrics.pick_ip();
                let pinned_addr = chosen_ip.as_ref().map(|ip| ip.addr);

                let client_key = (
                    node_idx,
                    pinned_addr.unwrap_or_else(|| SocketAddr::from(([0, 0, 0, 0], 0))),
                );
                let client = if let Some(c) = client_cache.get(&client_key) {
                    c.clone()
                } else {
                    let Some(c) = build_http1_client(
                        pinned_addr.map(|a| (node.host.as_str(), a)),
                        5,
                    ) else {
                        sleep_or_cancel(&cancel, Duration::from_millis(200)).await;
                        continue;
                    };
                    client_cache.insert(client_key, c.clone());
                    c
                };

                let http_post_size = node.metrics.current_post_bytes.load(Ordering::Relaxed);
                let last_progress_ms =
                    Arc::new(AtomicU64::new(start_instant.elapsed().as_millis() as u64));
                let pushed = Arc::new(AtomicUsize::new(0));
                let stream = InMemoryUploadStream {
                    chunk: payload.clone(),
                    offset: 0,
                    remaining: http_post_size,
                    stats: Some(stats.clone()),
                    node_metrics: Some(node.metrics.clone()),
                    pushed_bytes: pushed.clone(),
                    last_progress_ms: last_progress_ms.clone(),
                    start_instant,
                    cancel: cancel.clone(),
                };
                let body = reqwest::Body::wrap_stream(stream);

                stats.up_active_streams.fetch_add(1, Ordering::Relaxed);
                node.metrics.active_workers.fetch_add(1, Ordering::Relaxed);
                if let Some(ip) = &chosen_ip {
                    ip.active_conns.fetch_add(1, Ordering::Relaxed);
                    ip.total_conns.fetch_add(1, Ordering::Relaxed);
                }

                let req_t0 = Instant::now();
                let req_fut = client
                    .post(&node.url)
                    .header(reqwest::header::CONTENT_TYPE, "application/octet-stream")
                    .header(reqwest::header::CONTENT_LENGTH, http_post_size as u64)
                    .body(body)
                    .send();

                let lp_watch = last_progress_ms.clone();
                let stall_fut = async move {
                    loop {
                        tokio::time::sleep(Duration::from_secs(2)).await;
                        let now_ms = start_instant.elapsed().as_millis() as u64;
                        let prev = lp_watch.load(Ordering::Relaxed);
                        if now_ms.saturating_sub(prev) >= STALL_TIMEOUT_MS {
                            break;
                        }
                    }
                };

                enum UploadOutcome {
                    Done(Result<reqwest::Response, reqwest::Error>),
                    Stalled,
                }

                let outcome = tokio::select! {
                    biased;
                    _ = cancel.cancelled() => {
                        stats.up_active_streams.fetch_sub(1, Ordering::Relaxed);
                        node.metrics.active_workers.fetch_sub(1, Ordering::Relaxed);
                        if let Some(ip) = &chosen_ip {
                            ip.active_conns.fetch_sub(1, Ordering::Relaxed);
                        }
                        return;
                    }
                    res = req_fut => UploadOutcome::Done(res),
                    _ = stall_fut => UploadOutcome::Stalled,
                };

                stats.up_active_streams.fetch_sub(1, Ordering::Relaxed);
                node.metrics.active_workers.fetch_sub(1, Ordering::Relaxed);
                if let Some(ip) = &chosen_ip {
                    ip.active_conns.fetch_sub(1, Ordering::Relaxed);
                }

                match outcome {
                    UploadOutcome::Done(Ok(resp)) => {
                        let status = resp.status();
                        let sent = pushed.load(Ordering::Relaxed);
                        let elapsed_ms = req_t0.elapsed().as_millis().max(1) as u64;

                        if status.as_u16() == 413 && http_post_size > 256 * 1024 {
                            let next_size = (http_post_size / 2).max(256 * 1024);
                            node.metrics
                                .current_post_bytes
                                .store(next_size, Ordering::Relaxed);
                            stats.up_requests_fail.fetch_add(1, Ordering::Relaxed);
                            stats.up_errors.fetch_add(1, Ordering::Relaxed);
                            node.metrics.record_failure();
                            log_throttled(
                                &log,
                                &last_err_log_ms,
                                start_instant,
                                format!(
                                    "上行节点 [{}] 返回 413，自适应下调 POST 大小至 {}",
                                    node.host,
                                    format_bytes(next_size as u64)
                                ),
                            );
                        } else if is_complete_successful_upload(status, sent, http_post_size) {
                            // Count only a complete request body followed by a successful HTTP response.
                            // This is HTTP acceptance, not a byte-level server receipt acknowledgement.
                            let accepted = sent as u64;
                            stats.up_bytes_total.fetch_add(accepted, Ordering::Relaxed);
                            stats.up_requests_ok.fetch_add(1, Ordering::Relaxed);
                            stats.up_latency_ms.store(elapsed_ms, Ordering::Relaxed);

                            node.metrics.record_success(accepted, elapsed_ms);
                            if let Some(ip) = &chosen_ip {
                                ip.bytes_transferred.fetch_add(accepted, Ordering::Relaxed);
                                let ip_bps = ((accepted as f64) * 8.0 * 1000.0
                                    / (elapsed_ms as f64))
                                    as u64;
                                ip.current_bps.store(ip_bps, Ordering::Relaxed);
                            }

                            let next_sz = adapt_post_size(http_post_size, elapsed_ms);
                            if next_sz != http_post_size {
                                node.metrics
                                    .current_post_bytes
                                    .store(next_sz, Ordering::Relaxed);
                            }
                        } else {
                            stats.up_requests_fail.fetch_add(1, Ordering::Relaxed);
                            stats.up_errors.fetch_add(1, Ordering::Relaxed);
                            node.metrics.record_failure();
                            if let Some(ip) = &chosen_ip {
                                ip.errors.fetch_add(1, Ordering::Relaxed);
                            }
                            log_throttled(
                                &log,
                                &last_err_log_ms,
                                start_instant,
                                format!("上行 HTTP 状态异常 [{status}] [{}]", node.host),
                            );
                            sleep_or_cancel(&cancel, Duration::from_millis(200)).await;
                        }
                    }
                    UploadOutcome::Done(Err(e)) => {
                        stats.up_requests_fail.fetch_add(1, Ordering::Relaxed);
                        stats.up_errors.fetch_add(1, Ordering::Relaxed);
                        node.metrics.record_failure();
                        if let Some(ip) = &chosen_ip {
                            ip.errors.fetch_add(1, Ordering::Relaxed);
                        }
                        client_cache.remove(&client_key);
                        log_throttled(
                            &log,
                            &last_err_log_ms,
                            start_instant,
                            format!("上行 POST 失败 [{}]: {e}", node.host),
                        );
                        sleep_or_cancel(&cancel, Duration::from_millis(200)).await;
                    }
                    UploadOutcome::Stalled => {
                        stats.up_requests_fail.fetch_add(1, Ordering::Relaxed);
                        stats.up_errors.fetch_add(1, Ordering::Relaxed);
                        node.metrics.record_failure();
                        if let Some(ip) = &chosen_ip {
                            ip.errors.fetch_add(1, Ordering::Relaxed);
                        }
                        client_cache.remove(&client_key);
                        log_throttled(
                            &log,
                            &last_err_log_ms,
                            start_instant,
                            format!("上行流卡顿超时，自动重建连接并切换节点 [{}]", node.host),
                        );
                    }
                }
            }
        });
    }

    let _ = coord_task.await;
    while workers.join_next().await.is_some() {}
    stats.up_active_streams.store(0, Ordering::Relaxed);

    let body_yielded = stats.up_bytes_body_yielded.load(Ordering::Relaxed);
    let http_accepted = stats.up_bytes_total.load(Ordering::Relaxed);
    let avg = stats.up_bps_avg.load(Ordering::Relaxed);
    let peak = stats.up_bps_peak.load(Ordering::Relaxed);
    let p95 = stats.up_bps_p95.load(Ordering::Relaxed);
    let best_c = stats.up_best_concurrency.load(Ordering::Relaxed);
    let fail_pct = stats.up_fail_rate_pct();

    log.push(format!(
        "上行测速结束：有效平均 {} | 峰值 {} | P95 {} | 最佳并发 {best_c} | 失败率 {fail_pct:.1}%",
        format_mbps(avg),
        format_mbps(peak),
        format_mbps(p95),
    ));
    log.push(format!(
        "上行流量口径：HTTP Body 已交给客户端发送流 {} | 完整请求体后收到 2xx 响应 {}（非逐字节服务端 ACK）",
        format_bytes(body_yielded),
        format_bytes(http_accepted)
    ));
    log_upload_node_report(&nodes, &log);
}

fn log_upload_node_report(nodes: &[UploadNode], log: &MemoryLog) {
    log.push("[上行节点与多 IP 分布明细]:");
    for n in nodes {
        let m = &n.metrics;
        let ema = m.ema_bps.load(Ordering::Relaxed);
        let ok = m.requests_ok.load(Ordering::Relaxed);
        let fail = m.requests_fail.load(Ordering::Relaxed);
        let post_sz = m.current_post_bytes.load(Ordering::Relaxed);
        let lat = m.avg_latency_ms();
        let bytes = m.bytes_http_accepted.load(Ordering::Relaxed);
        log.push(format!(
            "  · {} | 速率:{} | 确认:{} | 请求成/败:{ok}/{fail} | POST:{} | 平均延迟:{lat}ms",
            m.host,
            format_mbps(ema),
            format_bytes(bytes),
            format_bytes(post_sz as u64)
        ));
        for ip in &m.ip_metrics {
            let tc = ip.total_conns.load(Ordering::Relaxed);
            if tc > 0 {
                let ib = ip.bytes_transferred.load(Ordering::Relaxed);
                let ibps = ip.current_bps.load(Ordering::Relaxed);
                let ie = ip.errors.load(Ordering::Relaxed);
                log.push(format!(
                    "      IP {} -> 连接:{tc} | HTTP接受:{} | 速率:{} | 错误:{ie}",
                    ip.addr,
                    format_bytes(ib),
                    format_mbps(ibps)
                ));
            }
        }
    }
}

async fn sleep_or_cancel(cancel: &CancelToken, dur: Duration) {
    tokio::select! {
        _ = cancel.cancelled() => {},
        _ = tokio::time::sleep(dur) => {},
    }
}

fn log_throttled(
    log: &MemoryLog,
    last_ms: &AtomicU64,
    start: tokio::time::Instant,
    msg: String,
) {
    let now_ms = start.elapsed().as_millis() as u64;
    let prev = last_ms.load(Ordering::Relaxed);
    if now_ms.saturating_sub(prev) >= 2000
        && last_ms
            .compare_exchange(prev, now_ms, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
    {
        log.push(msg);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_random_bytes_in_memory() {
        let b1 = make_in_memory_random_bytes(1024);
        assert_eq!(b1.len(), 1024);
        assert!(b1.iter().any(|&x| x != 0));
    }

    #[test]
    fn test_parse_http_upload_targets_excludes_raw_tcp() {
        let (http, rejected) = parse_http_upload_targets(&[
            "https://speed.cloudflare.com/__up".to_string(),
            "tcp://127.0.0.1:9000".to_string(),
            "192.168.1.10:5201".to_string(),
        ]);
        assert_eq!(http, vec!["https://speed.cloudflare.com/__up"]);
        assert_eq!(rejected.len(), 2);
    }

    #[test]
    fn test_only_complete_successful_http_requests_are_counted() {
        use reqwest::StatusCode;
        assert!(is_complete_successful_upload(StatusCode::OK, 1024, 1024));
        assert!(!is_complete_successful_upload(StatusCode::OK, 512, 1024));
        assert!(!is_complete_successful_upload(StatusCode::BAD_REQUEST, 1024, 1024));
        assert!(!is_complete_successful_upload(StatusCode::TOO_MANY_REQUESTS, 1024, 1024));
        assert!(!is_complete_successful_upload(StatusCode::INTERNAL_SERVER_ERROR, 1024, 1024));
    }

    #[test]
    fn test_adapt_post_size_tiers() {
        let s1 = adapt_post_size(4 * 1024 * 1024, 300, false);
        assert_eq!(s1, 8 * 1024 * 1024);
        let s2 = adapt_post_size(s1, 300);
        assert_eq!(s2, 16 * 1024 * 1024);
        let s3 = adapt_post_size(s2, 300);
        assert_eq!(s3, 32 * 1024 * 1024);
        let s4 = adapt_post_size(s3, 5000);
        assert_eq!(s4, 16 * 1024 * 1024);
    }
}
